/**
 * Hand-authored extras for the stroke font. Kept separate from
 * hershey-data.js because that file is regenerated by
 * tools/build-hershey.mjs and would otherwise wipe these glyphs.
 *
 * Coordinate system matches HERSHEY: y=0 baseline, y=1 cap-top,
 * x grows right, descenders go negative.
 */

// 16-segment circle as a closed polyline: 17 points, first==last.
function circle(cx, cy, r) {
    const pts = [];
    for (let i = 0; i <= 16; i++) {
        const a = (i / 16) * 2 * Math.PI;
        pts.push([
            +(cx + r * Math.cos(a)).toFixed(3),
            +(cy + r * Math.sin(a)).toFixed(3),
        ]);
    }
    return pts;
}

// Open arc from angle `a0` to `a1` (degrees, CCW), `n` samples.
function arc(cx, cy, r, a0, a1, n) {
    const pts = [];
    for (let i = 0; i <= n; i++) {
        const a = ((a0 + (a1 - a0) * (i / n)) * Math.PI) / 180;
        pts.push([
            +(cx + r * Math.cos(a)).toFixed(3),
            +(cy + r * Math.sin(a)).toFixed(3),
        ]);
    }
    return pts;
}

// Tiny diamond ~"dot" centred at (cx, cy) with half-size h.
function dot(cx, cy, h = 0.05) {
    return [
        [+(cx + h).toFixed(3), +cy.toFixed(3)],
        [+cx.toFixed(3),       +(cy + h).toFixed(3)],
        [+(cx - h).toFixed(3), +cy.toFixed(3)],
        [+cx.toFixed(3),       +(cy - h).toFixed(3)],
        [+(cx + h).toFixed(3), +cy.toFixed(3)],
    ];
}

export const EXTRA_GLYPHS = {
    // Override Hershey '.' and ',': place dot just above the true
    // baseline (y = -0.313 in this font, matching the bottom of 'H').
    '.': { w: 0.5, s: [[[0.25,-0.188],[0.188,-0.25],[0.25,-0.313],[0.313,-0.25],[0.25,-0.188]]] },
    ',': { w: 0.5, s: [[[0.313,-0.25],[0.25,-0.313],[0.188,-0.25],[0.25,-0.188],[0.313,-0.25],[0.313,-0.438],[0.188,-0.563]]] },
    // © Copyright: outer circle + open C in the middle.
    // Sized to match Hershey cap-height: glyphs span y in [-0.313, 1.0].
    '\u00A9': {
        w: 1.5,
        s: [
            circle(0.75, 0.344, 0.656),
            arc(0.75, 0.344, 0.36, 60, 300, 8),
        ],
    },
    // ® Registered: outer circle + small R.
    '\u00AE': {
        w: 1.5,
        s: [
            circle(0.75, 0.344, 0.656),
            // R: vertical stem + bowl + leg, sized to fit inside circle
            [[0.52, -0.05], [0.52, 0.7], [0.85, 0.7], [0.95, 0.625],
             [0.95, 0.45], [0.85, 0.375], [0.52, 0.375]],
            [[0.75, 0.375], [0.98, -0.05]],
        ],
    },
    // ™ Trademark: superscript T and M in the upper half.
    '\u2122': {
        w: 1.25,
        s: [
            // T
            [[0.05, 1.0], [0.55, 1.0]],
            [[0.30, 1.0], [0.30, 0.5]],
            // M
            [[0.65, 0.5], [0.65, 1.0], [0.925, 0.55], [1.20, 1.0], [1.20, 0.5]],
        ],
    },
    // ° Degree: small circle in the upper portion.
    '\u00B0': {
        w: 0.5,
        s: [circle(0.25, 0.85, 0.15)],
    },
    // µ Micro: same u shape as before, shifted down by ~0.313 so the
    // bottom of the bowl rests on the baseline; left stem extends
    // further below to form the descender.
    '\u00B5': {
        w: 1.125,
        s: [
            // Left stem: top at x-height, extended down for descender.
            [[0.25, 0.375], [0.25, -0.625]],
            // u bowl + right stem (bowl bottom at y = -0.313 = baseline)
            [[0.25, -0.125], [0.313, -0.25], [0.563, -0.313],
             [0.813, -0.25], [0.875, -0.125], [0.875, 0.375]],
        ],
    },
    // Ω Ohm/Omega: classic horseshoe with feet.
    // Sized to Hershey cap range y in [-0.313, 1.0].
    '\u03A9': {
        w: 1.5,
        s: [[
            [0.05, -0.313], [0.45, -0.313], [0.50, -0.25],
            [0.32, 0.0], [0.25, 0.35], [0.32, 0.70],
            [0.50, 0.92], [0.75, 1.0], [1.00, 0.92],
            [1.18, 0.70], [1.25, 0.35], [1.18, 0.0],
            [1.00, -0.25], [1.05, -0.313], [1.45, -0.313],
        ]],
    },
    // ± Plus-minus.
    '\u00B1': {
        w: 1.625,
        s: [
            [[0.813, 0.813], [0.813, 0.0]],
            [[0.25, 0.4], [1.375, 0.4]],
            [[0.25, -0.3], [1.375, -0.3]],
        ],
    },
    // × Multiplication sign.
    '\u00D7': {
        w: 1.625,
        s: [
            [[0.45, 0.55], [1.175, -0.05]],
            [[0.45, -0.05], [1.175, 0.55]],
        ],
    },
    // ÷ Division sign.
    '\u00F7': {
        w: 1.625,
        s: [
            [[0.25, 0.25], [1.375, 0.25]],
            dot(0.813, 0.6),
            dot(0.813, -0.1),
        ],
    },
};
